/*
 * Definitions for gentrap causes.  They are generated by user-level
 * programs and therefore should be compatible with the corresponding
 * OSF/1 definitions.
 */
pub const GEN_INTOVF: i32 = -1; // integer overflow
pub const GEN_INTDIV: i32 = -2; // integer division by zero
pub const GEN_FLTOVF: i32 = -3; // fp overflow
pub const GEN_FLTDIV: i32 = -4; // fp division by zero
pub const GEN_FLTUND: i32 = -5; // fp underflow
pub const GEN_FLTINV: i32 = -6; // invalid fp operand
pub const GEN_FLTINE: i32 = -7; // inexact fp operand
pub const GEN_DECOVF: i32 = -8; // decimal overflow (for COBOL??)
pub const GEN_DECDIV: i32 = -9; // decimal division by zero
pub const GEN_DECINV: i32 = -10; // invalid decimal operand
pub const GEN_ROPRAND: i32 = -11; // reserved operand
pub const GEN_ASSERTERR: i32 = -12; // assertion error
pub const GEN_NULPTRERR: i32 = -13; // null pointer error
pub const GEN_STKOVF: i32 = -14; // stack overflow
pub const GEN_STRLENERR: i32 = -15; // string length error
pub const GEN_SUBSTRERR: i32 = -16; // substring error
pub const GEN_RANGERR: i32 = -17; // range error
pub const GEN_SUBRNG: i32 = -18;
pub const GEN_SUBRNG1: i32 = -19;
pub const GEN_SUBRNG2: i32 = -20;
pub const GEN_SUBRNG3: i32 = -21; // these report range errors for
pub const GEN_SUBRNG4: i32 = -22; // subscripting (indexing) at levels 0..7
pub const GEN_SUBRNG5: i32 = -23;
pub const GEN_SUBRNG6: i32 = -24;
pub const GEN_SUBRNG7: i32 = -25;

/* the remaining codes (-26..-1023) are reserved. */

